/** Stichwörter einer Übung (leer für eigene Übungen) */
const KEYWORDS = new Map(CATALOG.map((c) => [c.name.toLowerCase(), c.keywords]));
export const keywordsOf = (name: string): string => KEYWORDS.get(name.toLowerCase()) ?? '';

/** Muskeln der Standardübungen, nach Namen */
export const CATALOG_MUSCLES: Record<string, MuscleId[]> = Object.fromEntries(CATALOG.filter((c) => c.type === 'strength').map((c) => [c.name, c.muscles]));

